def add_tax(amount, rate_percent):
    """Gross amount including ``rate_percent`` percent tax.

    The tax rate must be between 0 and 100 inclusive. The result is rounded
    to the cent using the finance team's rounding policy.

    Example:
        >>> add_tax(Decimal("100.00"), 8)
        Decimal('108.00')
    """
    if isinstance(rate_percent, bool) or not isinstance(rate_percent, (int, float)):
        raise BillingError("invalid_rate", repr(rate_percent))
    if not 0 <= rate_percent <= 100:
        raise BillingError("invalid_rate", f"rate must be between 0 and 100, got {rate_percent!r}")
    amount = to_money(amount)
    rate = Decimal(str(rate_percent))
    return round_money(amount * (1 + rate / 100))
